// Read the rule files reviewlore wrote into .claude/rules/ — by the plugin
// skill or by `run` — back into a plain shape, so `export` can turn the
// reviewed rules (the source of truth) into other tools' formats.
//
//   { id, title, body, why, paths[], examples[{ quote, author, pr, url }], file }
//
// Hand-written rules (no "Generated by reviewlore" line) are never read.

import { readdirSync, readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const PROVENANCE = "<!-- Generated by reviewlore";
const NAME_RE = /^pr-feedback-([a-z0-9]+(?:-[a-z0-9]+)*)\.md$/;
const CITATION_RE = /^\s*— @(\S+) on PR #(\d+): (\S+)\s*$/;

export function parseRuleFile(text, fileName) {
  const id = fileName.match(NAME_RE)?.[1];
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  if (!id || !text.includes(PROVENANCE)) return null;

  let i = 0;
  const paths = [];
  if (lines[0] === "---") {
    const end = lines.indexOf("---", 1);
    for (const line of lines.slice(1, end)) {
      const m = line.match(/^\s+-\s+"?([^"]+?)"?\s*$/);
      if (m) paths.push(m[1]);
    }
    i = end + 1;
  }

  const h1 = lines.findIndex((l, n) => n >= i && l.startsWith("# "));
  if (h1 === -1) return null;
  const title = lines[h1].slice(2).trim();
  const examplesAt = lines.findIndex((l) => l.trim() === "## Examples from PR review history");
  const section = lines.slice(h1 + 1, examplesAt === -1 ? lines.length : examplesAt);
  const whyAt = section.findIndex((l) => l.startsWith("**Why:**"));

  const prose = (arr) => arr.filter((l) => !l.startsWith("<!--")).join("\n").trim();
  const body = prose(whyAt === -1 ? section : section.slice(0, whyAt));
  let why = "";
  if (whyAt !== -1) {
    const rest = section.slice(whyAt);
    const stop = rest.findIndex((l, n) => n > 0 && (l.startsWith("**") || l.startsWith("#")));
    why = prose(stop === -1 ? rest : rest.slice(0, stop)).replace(/^\*\*Why:\*\*\s*/, "");
  }

  const examples = [];
  if (examplesAt !== -1) {
    let quote = null;
    for (const line of lines.slice(examplesAt + 1)) {
      if (line.startsWith("## ")) break;
      if (line.startsWith("- > ")) quote = line.slice(4);
      else if (quote !== null && line.startsWith("  > ")) quote += ` ${line.slice(4)}`;
      else if (quote !== null) {
        const m = line.match(CITATION_RE);
        if (m) {
          examples.push({ quote, author: m[1], pr: Number(m[2]), url: m[3] });
          quote = null;
        }
      }
    }
  }
  return { id, title, body, why, paths, examples, file: fileName };
}

// Every reviewlore-written rule in <targetDir>/.claude/rules, by id.
export function listGeneratedRules(targetDir) {
  const dir = join(targetDir, ".claude", "rules");
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((f) => NAME_RE.test(f))
    .sort()
    .map((f) => parseRuleFile(readFileSync(join(dir, f), "utf-8"), f))
    .filter(Boolean);
}
